export interface UserSubmittedIndianPhoneReport {
  /** Normalized 10-digit Indian mobile number. */
  number: string;
  /** User-submitted records are never treated as verified. */
  verificationStatus: "unverified";
  /** Source label supplied for this imported list. */
  source: string;
  /** Date this list was imported into ScamCheck. */
  importDate: string;
}

export interface VerifiedIndianPhoneReport {
  /** Normalized 10-digit Indian mobile number. */
  number: string;
  /** Only manually reviewed credible-source records belong in this list. */
  verificationStatus: "verified";
  source: string;
  reportDate: string;
  /** Concise explanation supported by the cited source. */
  evidenceSummary: string;
}

